ALTER TABLE "recruiter_grade" ADD COLUMN "weighted_grade" text;--> statement-breakpoint
ALTER TABLE "recruiter_grade" ADD COLUMN "weighted_points" integer;--> statement-breakpoint
ALTER TABLE "recruiter_grade" ADD COLUMN "weights_position" bigint;--> statement-breakpoint
ALTER TABLE "recruiter_grade" ADD CONSTRAINT "recruiter_grade_weighted_whole" CHECK (("recruiter_grade"."weighted_grade" is null and "recruiter_grade"."weighted_points" is null and "recruiter_grade"."weights_position" is null) or ("recruiter_grade"."weighted_grade" is not null and "recruiter_grade"."weighted_points" is not null and "recruiter_grade"."weights_position" is not null and "recruiter_grade"."weighted_grade" in ('A', 'B', 'C', 'D', 'F') and "recruiter_grade"."weighted_points" between "recruiter_grade"."points" - 2 and "recruiter_grade"."points" + 2 and "recruiter_grade"."weights_position" > 0));--> statement-breakpoint
ALTER TABLE "recruiter_grade" ADD CONSTRAINT "recruiter_grade_weighted_keeps_cap" CHECK ("recruiter_grade"."weighted_grade" is null or not ("recruiter_grade"."reasons" && array['dealbreaker', 'red_flag:upfront_fee', 'red_flag:sensitive_data', 'red_flag:vague_role', 'red_flag:unpaid_work']::text[]) or strpos('ABCDF', "recruiter_grade"."weighted_grade") >= strpos('ABCDF', "recruiter_grade"."grade"));
